self.addEventListener("push",i=>{let n=i.data?.json()??{};i.waitUntil(self.registration.showNotification(n.title??"Eden",{body:n.body??"",icon:"/icons/icon-192.png",badge:"/icons/icon-192.png",data:{url:n.url??"/tasks"}}))}),self.addEventListener("notificationclick",i=>{i.notification.close(),i.waitUntil(clients.matchAll({type:"window"}).then(n=>{let t=i.notification.data?.url??"/tasks";for(let i of n)if(i.url.includes(t)&&"focus"in i)return i.focus();if(clients.openWindow)return clients.openWindow(t)}))});